// Recount the words independently and check every version of the fold.
const fold = nb.get('fold');
if (!fold) return 'Run the cell above first.';

const mine = {};
for (const w of fold.words) mine[w] = (mine[w] || 0) + 1;
const final = fold.versions.at(-1);
const same = Object.keys(mine).length === Object.keys(final).length && Object.keys(mine).every(w => mine[w] === final[w]);

// each version must be the one before plus exactly one word
let oneStep = true;
for (let i = 1; i < fold.versions.length; i++) {
  const a = fold.versions[i - 1], b = fold.versions[i], w = fold.words[i - 1];
  const changed = Object.keys(b).filter(key => b[key] !== a[key]);
  if (changed.length !== 1 || changed[0] !== w || b[w] !== (a[w] || 0) + 1) oneStep = false;
}
const sizes = fold.versions.map(v => Object.values(v).reduce((s, n) => s + n, 0));

console.log(fold.lang + ': the shared tail is the very same object: ' + fold.shared);
console.log('JavaScript recount matches the final map: ' + same);
console.log('every version is the one before plus one word: ' + oneStep);
console.log(fold.versions.length + ' versions kept; version 5 still counts ' + sizes[5] + ' words, the last ' + sizes.at(-1));

const top = Object.entries(final).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, 8)
  .map(([word, count]) => ({ word, count }));
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 220,
  title: 'Most frequent words (' + fold.words.length + ' words, ' + Object.keys(final).length + ' different)',
  data: { values: top },
  mark: { type: 'bar', color: '#3b82f6' },
  encoding: {
    x: { field: 'word', type: 'nominal', sort: '-y', title: null },
    y: { field: 'count', type: 'quantitative', axis: { tickMinStep: 1 } },
  },
};
